/**
 * Deterministic text measurement + wrapping from the bundled fonts' advance widths
 * (src/catalog/font-metrics.json, generated by `npm run fonts`). No DOM, no canvas: the agent's
 * layout check (via the render worker's `check` command) and the templates call the SAME function,
 * so text that passes validation is laid out exactly as validated. Overflow is an error, never an
 * ellipsis.
 */
import metrics from '../catalog/font-metrics.json';

export type Weight = 400 | 700;
export type FitBox = { width: number; maxLines: number; size: number; weight: Weight };
export type FitReason = 'empty' | 'missing_glyph' | 'overflow_word' | 'overflow_lines';
export type FitResult = {
  ok: boolean;
  lines: string[];
  /** Widest line in px (markup stripped). */
  width: number;
  reason?: FitReason;
  missing?: string[];
};

const TABLES = metrics.weights as Record<string, Record<string, number>>;
/** Kerning and sub-pixel rounding can only shift widths slightly; keep a small safety margin. */
export const SAFETY = 1.03;

/** `*word*` marks highlights; markers take no space. */
export const stripMarkup = (text: string): string => text.replace(/\*/g, '');

export const missingGlyphs = (text: string, weight: Weight = 400): string[] => {
  const table = TABLES[String(weight)] ?? {};
  const out = new Set<string>();
  for (const ch of stripMarkup(text)) if (ch !== '\n' && table[ch] === undefined) out.add(ch);
  return [...out];
};

/** Width in px of a single line (no wrapping) at `size` px. Unknown glyphs count as 1 em. */
export const measure = (text: string, size: number, weight: Weight = 400): number => {
  const table = TABLES[String(weight)] ?? {};
  let em = 0;
  for (const ch of stripMarkup(text)) em += table[ch] ?? 1;
  return em * size * SAFETY;
};

/**
 * Greedy word wrap into `box`. Explicit `\n` forces a break. A word wider than the box is an
 * `overflow_word` (no hyphenation); more lines than `maxLines` is `overflow_lines`.
 */
export const fitText = (text: string, box: FitBox): FitResult => {
  const clean = text.trim();
  if (!stripMarkup(clean).trim()) return { ok: false, lines: [], width: 0, reason: 'empty' };
  const missing = missingGlyphs(clean, box.weight);
  const lines: string[] = [];
  let overflowWord = false;
  for (const para of clean.split('\n')) {
    let line = '';
    for (const word of para.split(/\s+/).filter(Boolean)) {
      if (measure(word, box.size, box.weight) > box.width) overflowWord = true;
      const candidate = line ? `${line} ${word}` : word;
      if (line && measure(candidate, box.size, box.weight) > box.width) {
        lines.push(line);
        line = word;
      } else {
        line = candidate;
      }
    }
    lines.push(line);
  }
  const width = Math.max(...lines.map((l) => measure(l, box.size, box.weight)));
  const reason: FitReason | undefined = missing.length
    ? 'missing_glyph'
    : overflowWord
      ? 'overflow_word'
      : lines.length > box.maxLines
        ? 'overflow_lines'
        : undefined;
  return { ok: !reason, lines, width, ...(reason ? { reason } : {}), ...(missing.length ? { missing } : {}) };
};

/** Largest size (stepping down by `step`, not below `min`) at which `text` fits; null if none. */
export const fitSize = (
  text: string,
  box: FitBox,
  min: number,
  step = 4,
): (FitResult & { size: number }) | null => {
  for (let size = box.size; size >= min; size -= step) {
    const r = fitText(text, { ...box, size });
    if (r.ok) return { ...r, size };
    if (r.reason === 'missing_glyph' || r.reason === 'empty') return null;
  }
  return null;
};

export type Segment = { text: string; hl: boolean };

/**
 * Splits wrapped lines into highlight segments. The highlight state carries across line breaks so
 * `*two words*` wrapped onto two lines stays highlighted.
 */
export const segmentLines = (lines: string[]): Segment[][] => {
  let hl = false;
  return lines.map((line) => {
    const segs: Segment[] = [];
    let buf = '';
    for (const ch of line) {
      if (ch === '*') {
        if (buf) segs.push({ text: buf, hl });
        buf = '';
        hl = !hl;
      } else {
        buf += ch;
      }
    }
    if (buf) segs.push({ text: buf, hl });
    return segs;
  });
};
